import urllib.request, json
for url in ['https://api.ivxholding.com/health','https://ivxholding.com','https://chat.ivxholding.com']:
 try:
  with urllib.request.urlopen(url, timeout=20) as response:
   raw=response.read()
   print(url, 'HTTP', response.status, 'bytes', len(raw))
   if url.endswith('/health'):
    data=json.loads(raw)
    print(json.dumps({key:data.get(key) for key in ['status','environment','commit','serviceName','bootTime','version']},indent=2))
 except Exception as error:
  print(url, 'ERROR', str(error))
